export interface DeliveryPlan {
  readonly subject: string
  readonly recipients: ReadonlyArray<string>
}

export interface DeliveryEnvelope {
  readonly to: string
  readonly cc: ReadonlyArray<string>
  readonly subject: string
}

function parseRecipients(input: unknown): readonly [string, ...string[]] {
  if (typeof input !== "string") {
    throw new Error("Recipients must be a comma-separated string")
  }

  const addresses = input.split(",").map((value) => value.trim())
  const [head, ...tail] = addresses
  if (head === undefined || head.length === 0) {
    throw new Error("At least one recipient is required")
  }
  if ([head, ...tail].some((address) => !address.includes("@"))) {
    throw new Error("Every recipient must be an email address")
  }
  return [head, ...tail]
}

export function createDeliveryPlan(
  subject: string,
  recipients: unknown
): DeliveryPlan {
  return { subject, recipients: parseRecipients(recipients) }
}

export function toEnvelope(plan: DeliveryPlan): DeliveryEnvelope {
  const [primary, ...copies] = plan.recipients
  if (primary === undefined) {
    throw new Error("Delivery plan unexpectedly has no recipients")
  }
  return { to: primary, cc: copies, subject: plan.subject }
}

